css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12.5px; margin-bottom: 4px; line-height: 1.35;}
.mz .recuerda-figuras{display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 5px;}
.mz .rf-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 4px 4px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 1px;}
.mz .rf-nombre{font-size: 12px; font-weight: 700;}
.mz .rf-info{font-family: sans-serif; font-size: 9.5px; color: #555;}
.mz .figura-svg{width: 38px; height: 38px;}
.mz .figura-mini{width: 40px; height: 40px;}
.mz .unir-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 40px; align-items: center;}
.mz .unir-col{display: flex; flex-direction: column; gap: 5px; align-items: center;}
.mz .unir-fig{display: flex; align-items: center; justify-content: center; min-height: 38px;}
.mz .unir-fig svg{width: 38px; height: 38px;}
.mz .unir-nom{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 8px; text-align: center; font-size: 13.5px; font-weight: 700; width: 100%;}
.mz .contar-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .contar-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 5px 4px; display: flex; flex-direction: column; align-items: center; gap: 3px;}
.mz .contar-linea{display: flex; align-items: center; gap: 5px; font-size: 11.5px; font-weight: 600;}
.mz .contar-hueco{width: 30px; height: 22px; border: 1.5px solid var(--bosque); border-radius: 5px; display: inline-block;}
.mz .rodear-mosaico{display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px;}
.mz .rodear-fig{border: 1.5px dashed #000; border-radius: 8px; padding: 3px; display: flex; align-items: center; justify-content: center; min-height: 44px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 5px;}
.mz .vf-item{display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; border-bottom: 1px dotted #999; padding-bottom: 3px;}
.mz .vf-opciones{font-family: sans-serif; font-weight: 700; font-size: 12.5px; white-space: nowrap;}
.mz .recuerda-idea{line-height: 1.725 !important;}
